// Value: protects=/sessions/[sessionId] hands SessionDetailPage canReverseLedger only with session_ledger.reverse and canViewPayroll only with payroll.view;
// fails_when=either flag keys off the wrong permission (e.g. sessions.lock), is hard-coded, or stops reaching the page, so the lock panel offers ledger reversal or payroll figures to the wrong role;
// why_new=permission wiring lives only in the route; SessionLockActions tests pass both flags as props;
// seam=none (loaders and SessionDetailPage mocked at module boundaries; returned element props inspected); no_claim=does not prove RLS, the reversal RPC's own check, or the real queries
import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import SessionDetailRoute from "@/app/(app)/sessions/[sessionId]/page";
import type { SessionDetailPage } from "@/features/sessions/session-detail-page";

const dependencies = vi.hoisted(() => ({
  getAdditionalStudyCandidates: vi.fn(),
  getCachedDatabasePermissions: vi.fn(),
  getSessionDetail: vi.fn(),
  SessionDetailPage: vi.fn(() => null),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/sessions/detail-data", () => ({ getSessionDetail: dependencies.getSessionDetail }));
vi.mock("@/features/sessions/attendance-data", () => ({ getAdditionalStudyCandidates: dependencies.getAdditionalStudyCandidates }));
vi.mock("@/features/sessions/session-detail-page", () => ({ SessionDetailPage: dependencies.SessionDetailPage }));

const sessionId = "fa70d806-18e0-4b04-af6e-b045156a13fa";

async function renderRoute(permissions: string[]) {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.getSessionDetail.mockResolvedValue({ detail: { id: sessionId, lockedAt: null, status: "scheduled" }, ok: true });
  dependencies.getAdditionalStudyCandidates.mockResolvedValue({ ok: true, students: [] });

  return (await SessionDetailRoute({
    params: Promise.resolve({ sessionId }),
    searchParams: Promise.resolve({}),
  })) as ReactElement<ComponentProps<typeof SessionDetailPage>>;
}

afterEach(() => {
  vi.clearAllMocks();
});

describe("Session detail route lock-panel permission wiring", () => {
  it("maps session_ledger.reverse to canReverseLedger and payroll.view to canViewPayroll", async () => {
    const without = await renderRoute(["sessions.view", "sessions.lock"]);
    expect(without.type).toBe(dependencies.SessionDetailPage);
    expect(without.props.canReverseLedger).toBe(false);
    expect(without.props.canViewPayroll).toBe(false);

    const reverseOnly = await renderRoute(["sessions.view", "sessions.lock", "session_ledger.reverse"]);
    expect(reverseOnly.props.canReverseLedger).toBe(true);
    expect(reverseOnly.props.canViewPayroll).toBe(false);

    const payrollOnly = await renderRoute(["sessions.view", "sessions.lock", "payroll.view"]);
    expect(payrollOnly.props.canReverseLedger).toBe(false);
    expect(payrollOnly.props.canViewPayroll).toBe(true);

    const both = await renderRoute(["sessions.view", "session_ledger.reverse", "payroll.view"]);
    expect(both.props.canReverseLedger).toBe(true);
    expect(both.props.canViewPayroll).toBe(true);
  });
});
